def bell_number(n):
    if n < 0:
        raise ValueError("n must be non-negative")

    bell = [0] * (n + 1)
    bell[0] = 1

    for size in range(1, n + 1):
        next_row = [0] * (n + 1)
        next_row[0] = bell[size - 1]

        for index in range(1, size + 1):
            next_row[index] = next_row[index - 1] + bell[index - 1]

        bell = next_row

    return bell[0]

