def follows_pattern(patterns, sequence):
    if isinstance(sequence, str):
        values = sequence.split()
    else:
        values = list(sequence)

    if len(patterns) != len(values):
        return False

    pattern_to_value = {}
    value_to_pattern = {}

    for pattern, value in zip(patterns, values):
        if pattern in pattern_to_value and pattern_to_value[pattern] != value:
            return False
        if value in value_to_pattern and value_to_pattern[value] != pattern:
            return False
        pattern_to_value[pattern] = value
        value_to_pattern[value] = pattern

    return True

