def next_smallest_palindrome(n):
    if n < 0:
        return 0

    digits = str(n)
    length = len(digits)
    half_length = (length + 1) // 2
    prefix = int(digits[:half_length])

    if length % 2:
        palindrome = int(str(prefix) + str(prefix // 10)[::-1])
    else:
        palindrome = int(str(prefix) + str(prefix)[::-1])

    if palindrome > n:
        return palindrome

    prefix += 1
    if len(str(prefix)) > half_length:
        return 10 ** length + 1

    if length % 2:
        return int(str(prefix) + str(prefix // 10)[::-1])
    return int(str(prefix) + str(prefix)[::-1])

