def eulerian(n, m):
    if n < 0 or m < 0 or m >= n:
        return 0
    values = [0] * (m + 1)
    values[0] = 1

    for size in range(1, n + 1):
        next_values = [0] * (m + 1)
        for ascents in range(min(m, size - 1) + 1):
            current = 0
            if ascents > 0:
                current += (size - ascents) * values[ascents - 1]
            current += (ascents + 1) * values[ascents]
            next_values[ascents] = current
        values = next_values

    return values[m]

