def is_magic_square(matrix):
    if not matrix or any(not isinstance(row, (list, tuple)) for row in matrix):
        return False

    size = len(matrix)
    if any(len(row) != size for row in matrix):
        return False

    values = [value for row in matrix for value in row]
    if any(not isinstance(value, int) or isinstance(value, bool) for value in values):
        return False

    expected_values = set(range(1, size * size + 1))
    if set(values) != expected_values:
        return False

    target_sum = sum(matrix[0])

    if any(sum(row) != target_sum for row in matrix):
        return False

    if any(sum(matrix[row][column] for row in range(size)) != target_sum
           for column in range(size)):
        return False

    main_diagonal = sum(matrix[index][index] for index in range(size))
    opposite_diagonal = sum(matrix[index][size - 1 - index] for index in range(size))

    return main_diagonal == target_sum and opposite_diagonal == target_sum

