def solve_diophantine(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd_value, coefficient_x, coefficient_y = extended_gcd(y, x % y)
        return gcd_value, coefficient_y, coefficient_x - (x // y) * coefficient_y

    gcd_value, coefficient_a, coefficient_b = extended_gcd(abs(a), abs(b))

    if n % gcd_value != 0:
        return None

    coefficient_a *= 1 if a >= 0 else -1
    coefficient_b *= 1 if b >= 0 else -1
    multiplier = n // gcd_value

    return coefficient_a * multiplier, coefficient_b * multiplier

