def is_majority_element(array, n, element):
    if n <= 0:
        return False

    left = 0
    right = n

    while left < right:
        middle = (left + right) // 2
        if array[middle] < element:
            left = middle + 1
        else:
            right = middle

    first = left
    if first >= n or array[first] != element:
        return False

