def count_sequences(m, n):
    previous = [0] + [1] * m

    for _ in range(1, n):
        prefix = [0] * (m + 1)
        for value in range(1, m + 1):
            prefix[value] = prefix[value - 1] + previous[value]

        current = [0] * (m + 1)
        for value in range(1, m + 1):
            current[value] = prefix[value // 2]

        previous = current

    return sum(previous)

