def longest_palindromic_subsequence(s):
    n = len(s)
    if n == 0:
        return 0

    lengths = [0] * n

    for start in range(n - 1, -1, -1):
        previous = 0
        lengths[start] = 1

        for end in range(start + 1, n):
            saved = lengths[end]

            if s[start] == s[end]:
                lengths[end] = previous + 2
            else:
                lengths[end] = max(lengths[end], lengths[end - 1])

            previous = saved

    return lengths[-1]

