def count_primes(n):
    if n <= 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = False
    is_prime[1] = False

    limit = int(n ** 0.5) + 1
    for number in range(2, limit):
        if is_prime[number]:
            start = number * number
            is_prime[start:n:number] = [False] * (((n - 1 - start) // number) + 1)

    return sum(is_prime)

