def kConcatenationMaxSum(arr, k):
    mod = 10**9 + 7
    total = sum(arr)

    best = current = arr[0]
    for value in arr[1:]:
        current = max(value, current + value)
        best = max(best, current)

    if k == 1:
        return best % mod

    current = best
    for value in arr:
        current = max(value, current + value)
        best = max(best, current)

    if total > 0:
        best += total * (k - 2)

    return best % mod

