def sum_of_divisors(number):
    number = abs(number)
    if number == 0:
        return 0

    total = 0
    divisor = 1
    while divisor * divisor <= number:
        if number % divisor == 0:
            total += divisor
            paired_divisor = number // divisor
            if paired_divisor != divisor:
                total += paired_divisor
        divisor += 1

    return total

